document.outline_text:
[
  {
    "intent": "Introduce why scenario test identity must outlive the calling terminal session.",
    "summary": "I shipped test-genie to own each scenario test run immediately after the command returns, ensuring the suite preserves its identity and evidence rather than vanishing when an agent session disconnects.",
    "target_words": 260
  },
  {
    "intent": "Explain the operational three-step workflow that decouples execution from continuous terminal attachment.",
    "summary": "Operators start the scenario suite, capture the durable run identifier, and wait once on the server-owned run, replacing brittle synchronous monitoring with an asynchronous checkpoint.",
    "target_words": 290
  },
  {
    "intent": "Clarify the diagnostic boundary between client transport drops and genuine product defects.",
    "summary": "Because a cancelled client is not the same thing as an aborted run, the system preserves the essential failure path distinction between transient infrastructure disconnects and real software defects.",
    "target_words": 310
  },
  {
    "intent": "Demonstrate how persistent validation evidence enables operator handoffs and control plane governance.",
    "summary": "By treating long-running validation as a governed capability, the server-owned record stays intact so subsequent builders can inspect durable evidence and make grounded decisions from the original run.",
    "target_words": 280
  }
]

